import {Link} from 'react-router-dom';
import '../styles/homepage.css';
import 'animate.css';
import NavMenu from "./SharedComponents/navMenu";
import CustomFooter from './SharedComponents/customFooter';
import workspace_icon from './Images/Home/collection/workspace.png';  // Ensure you have this image or replace with another

const Employee = () => {
  return (
    <div className="homepage">
      <NavMenu isHome={true} pagePath="/employee"/>
      <div className="cover-wrapper">
        <img src={employee_icon} alt="HR Cover"/>
      </div>
      <section className="scrolling-wrapper animate__animated animate__fadeInUp">
        <div className="tile-emp">
          <img src={workspace_icon} alt="View Workspaces"/>
          <Link to="/view-workspaces" className="form_btn">View Workspaces</Link>
        </div>
        {/* Other tiles */}
      </section>
      <CustomFooter/>
    </div>
  );
};

export default Employee;
